const initialTasks = [{id: "a", text: "Pack"}, {id: "b", text: "Check"}];
function without(tasks, id) {
  return tasks.filter(task => task.id !== id);
}
function App() {
  const [tasks, setTasks] = React.useState(initialTasks);
  return <main><ul>{tasks.map(task => <li key={task.id}>{task.text}
    <button onClick={() => setTasks(current => without(current, task.id))}>Remove {task.text}</button>
  </li>)}</ul><p role="status">Remaining: {tasks.length}</p></main>;
}

